CREATE PROCEDURE [CDN].[POS_EksportRodzajeCenKontrahentow]
	@rowVersion bigint,
	@PointOfSaleId int
AS
BEGIN
SET NOCOUNT ON;	
	declare @CentrumID INT = (select pck_centrumid from cdn.PicoKonfig join cdn.picostanowiska on psa_pckid=pck_picoid where psa_id=@PointOfSaleId)
	
	SELECT @rowVersion AS [@RowVersion]
		,(
		select distinct
		CenaLP as [@PriceTypeId],
		KntGUID as [@CustomerGUID]		
		from cdn.POS_KntDoEksportu(@PointOfSaleId,0)
		CROSS APPLY (select * from cdn.pos_tcnDoEksportu(@PointOfSaleId)) Ceny
		for xml path('CustomerPriceType'), type)
	for xml path('CustomerPriceTypes')
	SET NOCOUNT OFF;	
END
